<script>
import MainLayout from '../../layouts/MainLayout.vue';import MwListItem from '../../components/MwListItem.vue';import MwButton from '../../components/MwButton.vue';
export default { components: { MainLayout, MwListItem, MwButton }, computed: { wallet() { return this.$account.wallets().find(wallet => wallet.isAccountRecoverySupported); } }, methods: { open(name) { if (this.wallet) this.$router.push({name,params:{cryptoId:this.wallet.crypto._id}}); } } };
</script><template><MainLayout :title="$t('Advanced tools')"><p>{{ $t('These tools are for recovery and technical details. They do not add money.') }}</p><p>{{ $t('Select a network to view its receiving address.') }}</p><ul class="settings-advanced-view__list"><MwListItem v-if="wallet?.isExportSupported" :title="$t('Export private keys')" @click="open('crypto.export')" /><MwListItem v-if="wallet?.isSettingsSupported" :title="$t('Derivation path')" :description="$t('This path is fixed for your account. Changing it would create a different address.')" @click="open('crypto.derivation')" /><MwListItem v-if="$account.capabilities.hardwareSecurity" :title="$t('Hardware security')" @click="$router.push({name:'settings.hardware'})" /></ul><p v-if="!$account.capabilities.hardwareSecurity">{{ $t('Hardware security') }} · {{ $t('Not supported') }}</p><details><summary>{{ $t('Remove account') }}</summary><p>{{ $t('Account deletion is unavailable. Your funds and transaction records remain.') }}</p><MwButton type="danger-light" disabled>{{ $t('Remove account') }}</MwButton></details></MainLayout></template><style lang="scss">/* Hallmark · genre: modern-minimal · macrostructure: Workbench · design-system: design.md · pre-emit critique: P5 H5 E4 S5 R5 V4 */ .settings-advanced-view__list { list-style: none; margin: 0; padding: 0; }</style>
